func (r *review) GetFieldByName(fieldName string) (field.OrderExpr, bool) {
	_f, ok := r.fieldMap[fieldName]
	if !ok || _f == nil {
		return nil, false
	}
	_oe, ok := _f.(field.OrderExpr)
	return _oe, ok
}

func (r *review) fillFieldMap() {
	r.fieldMap = make(map[string]field.Expr, 9)
	r.fieldMap["id"] = r.ID
	r.fieldMap["user_id"] = r.UserID
	r.fieldMap["product_id"] = r.ProductID
	r.fieldMap["rating"] = r.Rating
	r.fieldMap["comment"] = r.Comment
	r.fieldMap["created_at"] = r.CreatedAt
	r.fieldMap["updated_at"] = r.UpdatedAt

}

func (r review) clone(db *gorm.DB) review {
	r.reviewDo.ReplaceConnPool(db.Statement.ConnPool)
	r.Users.db = db.Session(&gorm.Session{Initialized: true})
	r.Users.db.Statement.ConnPool = db.Statement.ConnPool
	r.Products.db = db.Session(&gorm.Session{Initialized: true})
	r.Products.db.Statement.ConnPool = db.Statement.ConnPool
	return r
}

func (r review) replaceDB(db *gorm.DB) review {
	r.reviewDo.ReplaceDB(db)
	r.Users.db = db.Session(&gorm.Session{})
	r.Products.db = db.Session(&gorm.Session{})
	return r
}

